Method.Implementation:
set origSettingFilePath = ..Adapter.FilePath
$$$TRACE("Adapter FilePath: " _ origSettingFilePath)

if ..OriginalPathParentFolder '= "" {
	$$$TRACE("Calling setPathFromOriginal method")
	do ..setPathFromOriginal(pRequest.OriginalFilename)
}

if ..UseDateFolders {
	$$$TRACE("Calling AddDateFolders method")
	set tSC = ..AddDateFolders()
}

set tSC=##super(pRequest,.pResponse)

if ..Adapter.FilePath '= origSettingFilePath {
	set ..Adapter.FilePath = origSettingFilePath
	$$$TRACE("Adapter FilePath set back to orginal setting: " _ ..Adapter.FilePath)
}

Quit tSC

	$$$TRACE("Entering IHC.ITF.ITFCOMMON.Operation.FileOperationWithDynamicPath.setPathfromOriginal")

	set OrigParentDir = ..OriginalPathParentFolder
	set AltParentDir = ..AlterativeParentFolder
	set RelativePath = ""

	set OriginalPath = OriginalFilename
	if OriginalPath["/" {
		Set lastSlash = $L(OriginalPath,"/")
		if lastSlash>1 {
			Set OriginalPath = $P(OriginalPath,"/",1,lastSlash-1)
		}	
		$$$TRACE("OriginalPath: " _ OriginalPath)


	    if OriginalPath[OrigParentDir {
		  set RelativePath = $P(OriginalPath,OrigParentDir,2,*)
	    }
	    else {
		  $$$TRACE(OrigParentDir _ " folder was not found in OriginalPath and thus defaulting to it alone as the destination child path")
	    }
	}
	else {
		$$$TRACE("OriginalPath does not contain a /. OriginalPath: " _ OriginalPath _ " Setting " _ OrigParentDir _ " as the destination child path")
	}

	if AltParentDir '= "" {
		Set RelativePath = AltParentDir _ RelativePath
	}
	else {
		Set RelativePath = OrigParentDir _ RelativePath
	}
	$$$TRACE("RelativePath: " _ RelativePath)

	set FilePath = ..Adapter.FilePath
	$$$TRACE("Adapter FilePath: " _ FilePath)

	if FilePath '= "" {
	   $$$TRACE("Adding RelativePath to Adapter FilePath as child path")
	   if $E(FilePath, *) = "/" {
		   //add child path
		   set ..Adapter.FilePath = FilePath _ RelativePath
       }	
	   else {
		   //add path seperator and then child path
		   set ..Adapter.FilePath = FilePath _ "/" _ RelativePath
	   }
	}
	else {
	   $$$TRACE("Setting Adapter FilePath as RelativePath since Adapter FilePath was blank")
	   set ..Adapter.FilePath = RelativePath
	}

	$$$TRACE("Adapter FilePath updated to: " _ ..Adapter.FilePath)

  	$$$TRACE("Entering IHC.ITF.ITFCOMMON.Operation.FileOperationWithDynamicPath.AddDateFolders")

	set pSpec = "%f/%Y/%m/%d"
    Set ts=##class(Ens.Util.Time).FormatDateTime(pSpec,..Adapter.FilePath)
    $$$TRACE("Append Date to the file path: " _ ts)

	set ..Adapter.FilePath = ts _"/"

  	$$$TRACE("Adapter.FilePath: " _ ..Adapter.FilePath)

  	if ('##class(%File).DirectoryExists(..Adapter.FilePath))
  	{
	  	set tSC = ##class(%File).CreateDirectoryChain(..Adapter.FilePath)
	  	if ($$$ISERR(tSC))
	  	{
		  	set ..Adapter.FilePath = FilePath
		  	return tSC
	  	}
  	}

  	set tSC = $$$OK
  	return tSC
